{
  "name": "WebDAV文件项",
  "name_en": "WebDAV File Entry",
  "manufacturer": "",
  "description": "WebDAV文件服务中的单个文件资源，用于在实验室网络或集群存储中公开数据文件。可用于查看文件属性并通过HTTP/WebDAV传输原始数据，如显微图像、分析结果或实验记录。",
  "description_en": "A single file resource in a WebDAV file service, used to expose data files on lab networks or cluster storage. It is used to inspect file properties and transfer raw data over HTTP/WebDAV, such as microscopy images, analysis outputs, or experiment records.",
  "actions": [
    {
      "action_name": "auto-getProperties",
      "description": "获取该WebDAV文件项的属性信息。",
      "description_en": "Get the properties of this WebDAV file entry."
    },
    {
      "action_name": "auto-sendData",
      "description": "发送该文件的数据内容给客户端。",
      "description_en": "Send the file data to the client."
    }
  ],
  "tag_hints": [
    "WebDAV file serving",
    "HTTP file transfer",
    "lab data storage",
    "file metadata retrieval",
    "cluster data access"
  ]
}

